const __vite__mapDeps=(i,m=__vite__mapDeps,d=(m.f||(m.f=["assets/air-pockets-velocity-BYkcHL--.js","assets/index-Cv6VCl5d.js","assets/index-CSeqFFJ7.css","assets/ArticleTag-BCz4VRd4.js","assets/analyzing-print-chart-modal-DMkO1w5s.js","assets/best-gex-tools-BDxzT2hU.js","assets/best-options-flow-tools-DYLB44s5.js","assets/best-vanna-tools-B47eA6Tw.js","assets/charm-D13YO4zx.js","assets/charts-first-CenrKffz.js","assets/dealer-positioning-BOQCrLRp.js","assets/delta-Cd-4RX9D.js","assets/execution-doctrine-DlsuZ8uy.js","assets/flow-highlighting-DfW8h751.js","assets/gamma-exposure-B5eLmlID.js","assets/gamma-regimes-9QCUF7yB.js","assets/gex-trading-jXDWSopz.js","assets/gex-vex-alignment-D9o1PA9A.js","assets/graduate-from-trading-alerts-DFo0WL6o.js","assets/heatseeker-patterns-BJGfTkLM.js","assets/intro-to-flowseeker--MD8vhzw.js","assets/intro-to-gamma-CcQTn_yw.js","assets/intro-to-talon-chatbot-v1-D-2wTMzX.js","assets/navigating-flowseeker-DeQBq-b1.js","assets/negative-gex-DGyh2aoe.js","assets/node-lifecycle-CiGoLA1r.js","assets/options-flow-DiXsvMuK.js","assets/options-greeks-BtOjFVAe.js","assets/reading-dark-pool-prints-DilPRljA.js","assets/reading-flow-on-atlas-8_ECmQ7X.js","assets/reading-heatseeker-Ctiqg34N.js","assets/rolling-floors-ceilings-inyRKDsI.js","assets/support-resistance-gex-BAQJeupE.js","assets/theta-DEsKVYpm.js","assets/trinity-mode-DtlnDfRq.js","assets/vanna-exposure-iF_8348n.js","assets/vega-aKzysskH.js","assets/vex-trading-rHmcs2jH.js","assets/vomma-tYFzzzzl.js"])))=>i.map(i=>d[i]);
